mapper.select:
SELECT * FROM t_goods WHERE deleted = 0
AND category_id = #{categoryId}
AND (title LIKE CONCAT('%', #{keyword}, '%') OR description LIKE CONCAT('%', #{keyword}, '%'))
AND price >= #{minPrice}
AND price <= #{maxPrice}
AND status = #{status}
AND user_id = #{userId}
ORDER BY create_time DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) FROM t_goods g
LEFT JOIN t_user u ON g.user_id = u.id AND u.deleted = 0
LEFT JOIN t_goods_category c ON g.category_id = c.id AND c.deleted = 0
WHERE g.deleted = 0
AND g.category_id = #{categoryId}

    AND (g.title LIKE CONCAT('%', #{keyword}, '%')
         OR g.description LIKE CONCAT('%', #{keyword}, '%')
         OR IFNULL(u.nickname, u.username) LIKE CONCAT('%', #{keyword}, '%')
         OR c.category_name LIKE CONCAT('%', #{keyword}, '%'))

AND g.price >= #{minPrice}
AND g.price <= #{maxPrice}
AND g.status = #{status}
AND g.user_id = #{userId}
AND g.create_time >= CURDATE()

mapper.update:
UPDATE t_goods
category_id = #{categoryId}, title = #{title}, description = #{description}, price = #{price}, original_price = #{originalPrice}, `condition` = #{condition}, cover_image = #{coverImage}, images = #{images}, status = #{status}, reject_reason = #{rejectReason}, stock = #{stock}, version = version + 1
WHERE id = #{id} AND deleted = 0 AND version = #{version}

mapper.select:
SELECT g.id, g.user_id, g.category_id, g.title, g.description, g.price, g.original_price, g.`condition`, g.cover_image, g.images, g.status, g.reject_reason, g.view_count, g.favorite_count, g.stock, g.create_time, IFNULL(u.nickname, u.username) AS username, u.avatar AS userAvatar, u.real_verified AS sellerRealVerified, c.category_name AS categoryName FROM t_goods g LEFT JOIN t_user u ON g.user_id = u.id AND u.deleted = 0 LEFT JOIN t_goods_category c ON g.category_id = c.id AND c.deleted = 0 WHERE g.deleted = 0 AND g.category_id = #{categoryId}
AND (g.title LIKE CONCAT('%', #{keyword}, '%') OR g.description LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(u.nickname, u.username) LIKE CONCAT('%', #{keyword}, '%') OR c.category_name LIKE CONCAT('%', #{keyword}, '%'))
AND g.price >= #{minPrice} AND g.price <= #{maxPrice} AND g.status = #{status} AND g.user_id = #{userId} AND g.create_time >= CURDATE()
ORDER BY g.price ASC, g.view_count DESC ORDER BY g.create_time DESC
LIMIT #{offset}, #{pageSize}

